import { z } from "zod";

/**
 * Reproducible contract build manifest (#1421).
 *
 * Generated by `scripts/verify-reproducible-build.ts` after building every
 * contract twice in clean target directories. The manifest records the exact
 * compiler/toolchain versions and the SHA-256 of each released WASM, and the
 * deploy scripts refuse to upload an artifact whose hash is not in it.
 */
const hashSchema = z.string().regex(/^[0-9a-f]{64}$/);

export const reproducibleBuildManifestSchema = z
  .object({
    version: z.literal(1),
    toolchain: z
      .object({
        builder: z.enum(["stellar", "cargo"]),
        rustc: z.string().min(1),
        sorobanSdk: z.string().min(1),
        stellarCli: z.string().min(1).nullable(),
        target: z.literal("wasm32v1-none"),
      })
      .strict(),
    contracts: z.record(z.string().min(1), hashSchema),
  })
  .strict();

export type ReproducibleBuildManifest = z.infer<
  typeof reproducibleBuildManifestSchema
>;

export interface HashMismatch {
  contract: string;
  expected: string | null;
  actual: string | null;
}

/**
 * Compares two sets of `contract -> hash` values. A contract present in only
 * one side is reported with a null on the missing side, so a build that stops
 * producing or starts producing a WASM never slips through as "no mismatch".
 */
export function hashMismatches(
  expected: Record<string, string>,
  actual: Record<string, string>
): HashMismatch[] {
  const names = [...new Set([...Object.keys(expected), ...Object.keys(actual)])]
    .sort()
    .map((contract) => {
      const expectedHash = expected[contract] ?? null;
      const actualHash = actual[contract] ?? null;
      return { contract, expected: expectedHash, actual: actualHash };
    });
  return names.filter((mismatch) => mismatch.expected !== mismatch.actual);
}

export function reproducibleBuildMismatches(
  manifest: ReproducibleBuildManifest,
  actual: Record<string, string>
): HashMismatch[] {
  return hashMismatches(manifest.contracts, actual);
}
